    SELECT 'estepas-salinas-mediterraneas-1510', '1510', 'Estepas salinas mediterráneas (Limonietalia)', 'Salino', 'Estepas de suelos salinos pero secos, sin encharcamiento permanente, en depresiones y llanos interiores de clima duro. Dominan el albardín (Lygeum spartum), una gramínea de matas separadas y hojas punzantes, y las siemprevivas (Limonium), que en verano cubren el suelo desnudo de flores diminutas rosas y violetas. Es un paisaje de aspecto pobre que concentra un número altísimo de plantas que no crecen en ningún otro ambiente.', 1, 37.386213, -1.624356, '#2e8b57', '{"type":"Polygon","coordinates":[[[-1.629491,37.386578],[-1.629383,37.386478],[-1.629283,37.386398],[-1.629197,37.386329],[-1.629082,37.386235],[-1.628953,37.386189],[-1.628838,37.386109],[-1.628724,37.38604],[-1.62861,37.385959],[-1.628495,37.385902],[-1.628337,37.385821],[-1.628223,37.385775],[-1.628122,37.385728],[-1.627993,37.385693],[-1.627864,37.385649],[-1.627721,37.385613],[-1.627577,37.385544],[-1.62742,37.385508],[-1.627262,37.38545],[-1.627118,37.385406],[-1.627003,37.385348],[-1.626846,37.385279],[-1.626731,37.385255],[-1.626616,37.385208],[-1.626487,37.385151],[-1.626359,37.385093],[-1.626243,37.385058],[-1.626115,37.384966],[-1.625986,37.384931],[-1.625957,37.384919],[-1.624867,37.384677],[-1.624751,37.3847],[-1.624623,37.384606],[-1.624493,37.384548],[-1.624379,37.384538],[-1.624278,37.384492],[-1.62415,37.3844],[-1.624049,37.384329],[-1.623949,37.384249],[-1.623864,37.384135],[-1.623778,37.383997],[-1.623721,37.383893],[-1.623693,37.383791],[-1.623693,37.383676],[-1.623651,37.383572],[-1.623608,37.383456],[-1.62358,37.383332],[-1.623552,37.383228],[-1.623524,37.383136],[-1.623424,37.382974],[-1.623367,37.382895],[-1.623267,37.382804],[-1.623167,37.382699],[-1.623038,37.38263],[-1.622909,37.382583],[-1.622794,37.382561],[-1.622636,37.382526],[-1.622507,37.382502],[-1.622392,37.38248],[-1.622278,37.382423],[-1.622149,37.382376],[-1.622019,37.382352],[-1.621919,37.382249],[-1.6218