    SELECT 'matorrales-termomediterraneos-y-5330', '5330', 'Matorrales termomediterráneos y pre-estépicos', 'Matorral', 'El matorral de las zonas más cálidas y secas, allí donde prácticamente no hiela: palmito, espino negro, lentisco, cornicales, bojas, albaidas y esparto sobre laderas pedregosas y llanos soleados. Es un matorral abierto, con suelo desnudo a la vista entre mata y mata, y con muchas especies compartidas con el norte de África. Aguanta sequías de meses y rebrota en cuanto llueve.', 0, 37.383614, -1.631935, '#daa520', '{"type":"MultiPolygon","coordinates":[[[[-1.64399,37.389036],[-1.643966,37.388958],[-1.643923,37.38882],[-1.643911,37.388789],[-1.643399,37.388091],[-1.643366,37.388074],[-1.643238,37.38798],[-1.643094,37.387889],[-1.642965,37.387797],[-1.642808,37.387716],[-1.642693,37.38767],[-1.642521,37.387612],[-1.642392,37.387579],[-1.642234,37.387543],[-1.642019,37.387507],[-1.641803,37.387484],[-1.641632,37.387462],[-1.641459,37.387415],[-1.641229,37.387381],[-1.641043,37.387345],[-1.640813,37.387322],[-1.64067,37.38732],[-1.640512,37.387298],[-1.640368,37.387296],[-1.64021,37.387274],[-1.640024,37.387238],[-1.639894,37.387239],[-1.639736,37.387215],[-1.639564,37.387181],[-1.639407,37.387134],[-1.639249,37.387076],[-1.639148,37.38703],[-1.638847,37.386984],[-1.638689,37.386937],[-1.638502,37.386903],[-1.638345,37.386856],[-1.638215,37.386798],[-1.638029,37.38674],[-1.637843,37.386661],[-1.637642,37.386591],[-1.637413,37.386521],[-1.637197,37.386476],[-1.637039,37.386429],[-1.636881,37.386382],[-1.636739,37.386324],[-1.636595,37.386255],[-1.636466,37.386174],[-1.636279,37.386059],[-1.636165,37.386002],[-1.636065,37.38591],[-1.635936,37.385805],[-1.635807,37.385714],[-1.635678,37.385645],[-1.635549,37.385564],[-1.635449,37.385473],[-1.635349,37.385357],[-1.63525,37.385232],[-1.63515,37.385105],[-1.635078,37.384991],[-1.635007,37.384853],[-1.634921,37.384737],[-1.634864,37.384646],[-1.634808,37.38453],[-1.634794,37.384415],[-1.634794,37.384289],[-1.