INSERT INTO species (park_id, common_name, scientific_name, kingdom, family, primary_habitat, conservation_status, description, description_source, identification_tips, seasonality, image_url, image_attribution, latitude, longitude, rarity_score, rarity_basis, rarity_local, rarity_local_basis, is_featured, is_visible, hidden_reason, source, taxon_phylum, taxon_class, taxon_order, taxon_family, taxon_genus, iucn_global, spain_status, murcia_status, review_note, eidos_taxonid, gbif_species_key, zepa_site_code, is_migratory, site_presence)
SELECT pk.id, s.common_name, s.scientific_name, s.kingdom, s.family, s.primary_habitat, s.conservation_status, s.description, s.description_source, s.identification_tips, s.seasonality, s.image_url, s.image_attribution, s.latitude, s.longitude, s.rarity_score, s.rarity_basis, s.rarity_local, s.rarity_local_basis, s.is_featured, s.is_visible, s.hidden_reason, s.source, s.taxon_phylum, s.taxon_class, s.taxon_order, s.taxon_family, s.taxon_genus, s.iucn_global, s.spain_status, s.murcia_status, s.review_note, s.eidos_taxonid, s.gbif_species_key, s.zepa_site_code, s.is_migratory, s.site_presence
FROM parks pk JOIN (
    SELECT 'Aulaga' common_name, 'Launaea arborescens' scientific_name, 'flora' kingdom, 'Mata' family, 'Matorral árido, ramblas y bordes de camino en clima muy seco' primary_habitat, 'En Peligro de Extinción' conservation_status, 'Mata en forma de bola formada por ramas verdes, rígidas y terminadas en pincho, casi sin hojas: la fotosíntesis la hacen los propios tallos. Al romper una rama suelta un látex blanco. Sus flores amarillas recuerdan a las del diente de león en miniatura.' description, NULL description_source, 'Matorral redondo de ramas verdes y espinosas, casi sin hojas; Suelta látex blanco al partir un tallo; Flores amarillas tipo diente de león' identification_tips, 'Primavera' seasonality, 'https://commons.wikimedia.org/wiki/Special:FilePath/Launaea_arborescens_-_Oasis_Park_botanical_garden_-_Fuerteventura_-_02.jpg?width=1280' image_url, 'Norbert Nagel, Mörfelden-Walldorf, Germany (CC BY-SA 3.0) · Wikimedia Commons' image_attribution, NULL latitude, NULL longitude, 1 rarity_score, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}' rarity_basis, 1 rarity_local, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}' rarity_local_basis, 0 is_featured, 1 is_visible, NULL hidden_reason, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 33 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).' source, 'Tracheophyta' taxon_phylum, 'Magnoliopsida' taxon_class, 'Asterales' taxon_order, 'Asteraceae' taxon_family, 'Launaea' taxon_genus, 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)' iucn_global, 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE' spain_status, 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia' murcia_status, NULL review_note, 9623 eidos_taxonid, 3144854 gbif_species_key, NULL zepa_site_code, NULL is_migratory, NULL site_presence
    UNION ALL
    SELECT 'Salao negro', 'Salsola oppositifolia', 'flora', 'Mata', 'Ramblas, taludes y matorrales sobre suelos salinos o removidos, en clima muy seco', 'No amenazada', 'Mata leñosa y ramosa, de hasta metro y medio, con hojas carnosas cortas y opuestas —de ahí el nombre— que dan a la planta un aspecto de escobilla gris azulada. Aguanta suelos salinos y alterados donde casi nada más prospera, y sus flores, diminutas, se reconocen porque el fruto queda envuelto en un ala membranosa circular.', NULL, 'Hojas carnosas y cortas dispuestas por pares, una frente a otra; Frutos con un ala redonda y translúcida, como una moneda de papel; Porte de escobilla gris azulada en taludes y bordes de rambla', 'Floración de verano a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Salsola_oppositifolia.JPG?width=1280', 'Retama (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del hábitat de interés comunitario 1430 según el Atlas y Manual de los Hábitat de España (MITECO, 2005), con presencia confirmada por 20 ocurrencia(s) de GBIF dentro de ese hábitat en este espacio. La cita de GBIF figura como Soda oppositifolia.', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Salsola', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 7914, 11364737, NULL, NULL, NULL
    UNION ALL
    SELECT 'Bolaga', 'Thymelaea hirsuta', 'flora', 'Mata', 'Matorral costero y semiárido, arenas y suelos pedregosos con influencia marina', 'No amenazada', 'Mata de ramas largas y flexibles cubiertas de hojitas escamosas, apretadas contra el tallo como las tejas de un tejado, con el envés blanco y peludo. Las flores son verdosas y pasan desapercibidas, pero su corteza es tan fibrosa y resistente que se ha usado tradicionalmente como cuerda.', NULL, 'Hojas minúsculas y solapadas, cubriendo el tallo como escamas; La rama no se rompe al doblarla: la corteza es fibrosa y correosa; Flores verde-amarillentas pegadas a la rama, sin pétalos vistosos', 'Floración de otoño a primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Thymelaea_hirsuta_Bonifacio.jpg?width=1280', 'Pancrat (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 17 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Thymelaeaceae', 'Thymelaea', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 8703, 5523602, NULL, NULL, NULL
    UNION ALL
    SELECT 'Morsana', 'Zygophyllum fabago', 'flora', 'Hierba', 'Suelos removidos, cunetas, ramblas y bordes de saladar en clima árido', 'No amenazada', 'Hierba perenne de tallos gruesos y quebradizos con hojas carnosas partidas en dos folíolos redondeados, como dos gotas verdes enfrentadas. Coloniza suelos pisoteados y salinos, y sus frutos alargados, en forma de cápsula estriada, cuelgan durante buena parte del verano.', NULL, 'Hojas de solo dos folíolos carnosos y redondeados; Tallos hinchados en los nudos, que se quiebran con facilidad; Cápsulas alargadas y acostilladas colgando tras la floración', 'Floración de primavera a verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Morsana-1.JPG?width=1280', 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 15 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Zygophyllales', 'Zygophyllaceae', 'Zygophyllum', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 9448, 3189902, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cornical', 'Periploca angustifolia', 'flora', 'Arbusto', 'Matorral cálido, laderas soleadas y barrancos de clima muy seco', 'Vulnerable (Región de Murcia)', 'Arbusto de hojas estrechas y coriáceas y flores pequeñas con cinco pétalos de un pardo verdoso y aspecto aterciopelado. Sus frutos son dos vainas largas y curvas dispuestas en forma de cuerno, de donde le viene el nombre popular de cornical. Suelta látex al romperse.', NULL, 'Frutos en dos vainas curvas enfrentadas, como cuernos; Látex blanco al partir una hoja o rama; Flores pardo verdosas con aspecto de terciopelo', 'Primavera y verano (floración)', 'https://inaturalist-open-data.s3.amazonaws.com/photos/609975159/original.jpg', 'Quentin Groom (CC0) · GBIF', NULL, NULL, 3, NULL, 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 14 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Periploca laevigata.', 'Tracheophyta', 'Magnoliopsida', 'Gentianales', 'Apocynaceae', 'Periploca', 'NE (no evaluada a nivel global)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 7034, 6022574, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sosa fina', 'Suaeda vera', 'flora', 'Mata', 'Bordes de saladar y suelos salinos algo más secos y elevados', 'Sensible a la alteración de su hábitat', 'Mata leñosa de hojas carnosas, cilíndricas y de un verde azulado, que ocupa la orla algo más alta y seca del saladar. Se diferencia de sus vecinas en que sí tiene hojas bien visibles y no tallos articulados. Sus flores son minúsculas y verdosas, en las axilas de las hojas.', NULL, 'Hojas carnosas y cilíndricas, verde azuladas; Base leñosa y ramificada, no herbácea; En la parte más seca y alta del saladar', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Suaeda_vera.JPG?width=1280', 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 11 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Suaeda', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 8507, 6035538, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cambrón', 'Lycium intricatum', 'flora', 'Arbusto', 'Matorral costero y suelos salinos y nitrificados de clima cálido', 'Especies de interés especial', 'Arbusto de ramas enmarañadas y espinosas, con hojitas carnosas agrupadas en manojos. Sus flores son pequeñas, tubulares y de color violeta pálido, y da bayas rojas que comen muchas aves. Forma setos impenetrables que dan refugio a pájaros y reptiles.', NULL, 'Ramas enredadas entre sí y terminadas en espina; Hojas carnosas en manojitos a lo largo de la rama; Bayas rojas pequeñas y flores tubulares violáceas', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lycium_intrincatum_(flor).JPG?width=1280', 'ANE (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 3, NULL, 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 11 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Solanales', 'Solanaceae', 'Lycium', 'NE (no evaluada a nivel global)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 5923, 3796884, NULL, NULL, NULL
    UNION ALL
    SELECT 'Siempreviva insigne', 'Limonium insigne', 'flora', 'Hierba', 'Suelos margosos y yesosos salinos, en estepas y taludes áridos', 'Especies de interés especial', 'Una de las siemprevivas más vistosas: sus inflorescencias forman un ramillete denso de un lila rosado intenso que destaca sobre el gris de las margas. Es un endemismo del sureste ibérico, ligado a suelos salinos y yesosos, y muy usado en seco como flor ornamental.', NULL, 'Floración densa y de lila rosado vivo, muy llamativa; Hojas en roseta basal, gruesas y de borde ondulado; Sobre margas y yesos claros, en terreno casi desnudo', 'Final de primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_insigne.jpg?width=1280', 'ANE (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 4, NULL, 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 10 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Plumbaginaceae', 'Limonium', 'NE (no evaluada a nivel global; género con numerosos microendemismos ibéricos)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 5836, 4088635, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jarilla de Mota', 'Helianthemum motae', 'flora', 'Mata', 'Matorrales abiertos y pastizales sobre suelos margosos y yesosos del sureste árido', 'No amenazada', 'Jarilla pequeña y grisácea, de hojas estrechas cubiertas de pelo blanquecino que reflejan la luz y le ahorran agua. Es un endemismo del sureste ibérico de área muy reducida, ligado a los suelos margosos de las zonas más áridas de la península.', NULL, 'Mata baja de aspecto plateado por el fieltro de pelos; Flores amarillas de cinco pétalos que duran un solo día; Hojas estrechas y enrolladas hacia el envés', 'Floración en primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/640806369/original.jpg', 'faluke (CC BY-NC 4.0) · iNaturalist/GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 9 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 31764, 7661033, NULL, NULL, NULL
    UNION ALL
    SELECT 'Rugueta de mar', 'Cakile maritima', 'flora', 'Hierba', 'Arena suelta de la primera línea de playa, sobre restos orgánicos del mar', 'No amenazada', 'Crucífera anual y carnosa que coloniza la arena batida donde el mar deposita algas. Sus hojas son gruesas y recortadas y sus flores, lilas o blancas, tienen los cuatro pétalos en cruz de la familia. El fruto se parte en dos: una mitad queda en la planta y la otra flota y viaja por mar.', NULL, 'Hojas carnosas y recortadas, algo azuladas; Flores lilas o blancas de cuatro pétalos en cruz; Frutos duros en dos piezas, como pequeños barrilitos', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cakile-maritima-(eurMeersenf)_1.jpg?width=1280', 'Jürgen Howaldt (CC BY-SA 2.0 de) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 9 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Brassicales', 'Brassicaceae', 'Cakile', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 2937, 3048831, NULL, NULL, NULL
    UNION ALL
    SELECT 'Margarita de mar', 'Asteriscus maritimus', 'flora', 'Mata', 'Playas y dunas fósiles del litoral', 'No amenazada', 'Mata que forma cojines sobre la roca litoral, con hojas espatuladas, carnosas y ásperas al tacto. Sus capítulos amarillos, casi sentados sobre el follaje, están rodeados de brácteas verdes que sobresalen entre las lígulas. Florece durante casi todo el año.', NULL, 'Cojines densos sobre roca costera; Brácteas verdes asomando entre los pétalos amarillos; Hojas espatuladas, carnosas y ásperas', 'Todo el año, floración prolongada', 'https://commons.wikimedia.org/wiki/Special:FilePath/Asteriscus_maritimus1.jpg?width=1280', 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 8 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Pallenis maritima.', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Asteriscus', 'NE (no evaluada a nivel global)', 'No catalogada en la Lista Roja de la Flora Vascular Española 2008', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 9925, 5385225, NULL, NULL, NULL
    UNION ALL
    SELECT 'Albardín', 'Lygeum spartum', 'flora', 'Gramínea', 'Estepas salinas, margas y suelos yesosos secos; forma albardinales', 'No amenazada', 'Gramínea perenne de hojas duras y punzantes que forma matas separadas sobre suelos salinos y margosos donde poco más prospera. Su inflorescencia es inconfundible: una espata blanca y sedosa que envuelve las flores como un capuchón de papel.', NULL, 'Espata blanca y sedosa envolviendo la espiga; Hojas rígidas terminadas en punta punzante; Matas espaciadas sobre suelo desnudo y claro', 'Todo el año (espigado en primavera)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lygeum_spartum-1.jpg?width=1280', 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 8 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Lygeum', 'LC', 'No catalogada en la Lista Roja de la Flora Vascular Española 2008', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 10060, 2704651, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jarilla de Almería', 'Helianthemum almeriense', 'flora', 'Mata', 'Tomillares y matorral abierto sobre suelos secos y pedregosos', 'No amenazada', 'Jarilla enana de hojas pequeñas y blanquecinas, cubiertas de pelos que reflejan la luz y reducen la pérdida de agua. En primavera se cubre de flores blancas con el centro amarillo, cuyos pétalos duran apenas una mañana. Sus raíces se asocian con hongos comestibles del desierto.', NULL, 'Mata baja y grisácea, de hojas muy pequeñas; Flores blancas con el centro amarillo, efímeras; Pétalos arrugados, como de papel de seda', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Helianthemum_almeriense_flor.jpg?width=1280', 'Retama (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 7 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 4958, 7331316, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lagartija colirroja', 'Acanthodactylus erythrurus', 'fauna', 'Reptil', 'Matorral litoral y laderas secas', 'Vulnerable', 'Lagartija de suelos arenosos, de cuerpo aplanado y dedos con escamas laterales en forma de peine que le sirven de raqueta sobre la arena suelta. Los jóvenes tienen la cola y las patas traseras de un rojo intenso que se apaga en los adultos.', NULL, 'Dedos con flecos de escamas a los lados, como peines; Jóvenes con cola y patas traseras rojo intenso; Cuerpo aplanado, con rayas y ocelos claros en el dorso', 'Primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Benny_Trapp_Acanthodactylus_erythrurus.jpg?width=1280', 'Benny Trapp (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 7 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Chordata', 'Reptilia', 'Squamata', 'Lacertidae', 'Acanthodactylus', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 11220, 5226733, NULL, NULL, NULL
    UNION ALL
    SELECT 'Salsola', 'Salsola papillosa', 'flora', 'Mata', 'Estepas salinas y suelos margosos y yesosos con sal', 'Vulnerable (Región de Murcia)', 'Mata baja y densa de hojas cortas y carnosas cubiertas de pequeñas papilas que le dan un tacto áspero. Es un endemismo ibérico ligado a suelos salinos y margosos, con una distribución muy fragmentada, lo que la hace especialmente sensible a la roturación.', NULL, 'Superficie de las hojas rugosa, con papilas visibles de cerca; Mata compacta y grisácea, de porte bajo; Frutos con alas membranosas al madurar', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Salsola_papillosa1160031.jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 5, NULL, 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 7 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Salsola', 'LC (Preocupación menor)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 7915, 3757043, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sosa jabonera', 'Halocnemum strobilaceum', 'flora', 'Planta suculenta', 'Saladares muy salinos con encharcamiento estacional', 'En peligro de extinción', 'Mata de tallos articulados y suculentos, con las ramas jóvenes agrupadas en apretados manojos que recuerdan a piñas diminutas, de donde le viene el nombre. Vive en los suelos más salinos del saladar, donde apenas compite con otras plantas.', NULL, 'Ramillas agrupadas en manojos con aspecto de piña; Tallos gruesos y articulados de color verde grisáceo; En las zonas más saladas y desnudas del saladar', 'Verano y otoño', 'https://inaturalist-open-data.s3.amazonaws.com/photos/611359925/original.jpg', 'Xavier Rufray (CC BY-NC 4.0) · iNaturalist/GBIF · obs. EAU (revisar: existe en salinas de España)', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 1, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 6 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Halocnemum', 'LC (amplia distribución circunmediterránea y saharo-arábiga)', 'No incluida en el LESRPE (RD 139/2011); propia de saladares prioritarios UE (HIC 1420)', 'Vulnerable (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 5051, 3760350, NULL, NULL, NULL
    UNION ALL
    SELECT 'Esparto', 'Macrochloa tenacissima', 'flora', 'Gramínea', 'Laderas secas y llanos sobre suelos pobres; forma espartales extensos', 'Vulnerable', 'El esparto, nombrado también como Stipa tenacissima, forma matas densas y duraderas que dan nombre a los espartales, uno de los paisajes característicos del sureste ibérico. Sus hojas se enrollan sobre sí mismas en los días secos para perder menos agua y se abren tras la lluvia. Durante siglos se recolectó para hacer cuerdas, esteras y alpargatas.', NULL, 'Matas grandes y compactas de hojas duras enrolladas; Las hojas se abren tras la lluvia y se enrollan al secar; Espigas altas y plateadas a final de primavera', 'Primavera (espigado)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stipa_tenacissima.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 6 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Macrochloa', 'VU (Vulnerable) (evaluación UICN 2018)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 27376, 4127897, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sosa alacranera', 'Arthrocnemum macrostachyum', 'flora', 'Planta suculenta', 'Saladares y marismas con encharcamiento salino prolongado', 'Sensible a la alteración de su hábitat', 'Planta sin hojas aparentes: sus tallos son cilíndricos, carnosos y divididos en segmentos que parecen articulaciones. Vive donde la sal se acumula y en otoño se tiñe de tonos rojizos y anaranjados que cambian el color de todo el saladar.', NULL, 'Tallos carnosos articulados, como collares de cuentas; Sin hojas visibles; Vira a rojo y naranja en otoño', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arthrocnemum_macrostachyum_2LaMata.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 5 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Arthrocaulon macrostachyum.', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Arthrocnemum', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 33034, 9417609, NULL, NULL, NULL
    UNION ALL
    SELECT 'Albardín brezo', 'Frankenia corymbosa', 'flora', 'Mata', 'Estepas salinas, saladares y suelos margosos con sal', 'No amenazada', 'Mata baja y muy ramificada, de hojas diminutas y enrolladas que a menudo aparecen cubiertas de una costra blanca: son cristales de sal que la planta expulsa por glándulas especializadas. Sus flores son rosadas y pequeñas, apiñadas en el extremo de las ramas.', NULL, 'Costra blanca de sal cristalizada sobre las hojas; Hojas minúsculas y enrolladas, casi como escamas; Flores rosadas pequeñas agrupadas en el extremo', 'Primavera y verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/464713930/original.jpeg', 'Rafael Medina (CC BY 4.0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del hábitat de interés comunitario 1420 según el Atlas y Manual de los Hábitat de España (MITECO, 2005), con presencia confirmada por 5 ocurrencia(s) de GBIF dentro de ese hábitat en este espacio.', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Frankeniaceae', 'Frankenia', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 4615, 3873636, NULL, NULL, NULL
    UNION ALL
    SELECT 'Zamarrilla lanuda', 'Teucrium lanigerum', 'flora', 'Mata aromática', 'Matorral y cerros sobre suelos calizos y margosos secos', 'Especies de interés especial', 'Mata cubierta por una lana blanca y espesa que la hace destacar en el matorral. Sus flores, rosadas o purpúreas, se agrupan en cabezuelas terminales y carecen de labio superior, con los estambres al descubierto. Es un endemismo del sureste ibérico.', NULL, 'Toda la planta cubierta de lana blanca y espesa; Flores sin labio superior, con los estambres asomando; Cabezuelas apretadas en el extremo de las ramas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Teucrium_lanigerum_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 5 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Teucrium', 'NE', 'No localizada en la Lista Roja de la Flora Vascular Española 2008', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 8809, 7308375, NULL, NULL, NULL
    UNION ALL
    SELECT 'Perfollada anual', 'Bupleurum semicompositum', 'flora', 'Hierba', 'Pastizales anuales, claros de matorral y suelos margosos secos', 'No amenazada', 'Umbelífera anual diminuta, de pocos centímetros, con hojas estrechas de un verde azulado y umbelas tan pequeñas que parecen botones. Es una de esas plantas efímeras que germinan con las lluvias, florecen deprisa y desaparecen antes del verano.', NULL, 'Planta anual muy pequeña, de aspecto rígido y verde azulado; Hojas lineares sin dientes, atravesadas por nervios paralelos; Umbelas minúsculas con brácteas que sobrepasan a las flores', 'Primavera', 'https://observation.org/photos/125530399.jpg', 'Humedales de Navarra (CC BY-NC-ND 4.0) · observation.org / GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 4 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Apiales', 'Apiaceae', 'Bupleurum', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 2852, 3636403, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cuernecillo de mar', 'Lotus creticus', 'flora', 'Hierba', 'Dunas móviles embrionarias', 'No amenazada', 'Leguminosa rastrera de follaje sedoso-plateado y flores amarillas, característica de las arenas litorales móviles.', NULL, 'Flores amarillas papilionadas; Follaje sedoso-plateado; Porte rastrero sobre arena', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/619207211/original.jpg', 'Augustin Soulard (CC BY 4.0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 4 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Lotus', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 6064, 5356939, NULL, NULL, NULL
    UNION ALL
    SELECT 'Anabasis', 'Anabasis hispanica', 'flora', 'Planta suculenta', 'Suelos salinos y margosos áridos, estepas y ramblas de clima muy seco', 'Especies de interés especial', 'Mata de tallos verdes, carnosos y articulados, sin hojas visibles, muy parecida a las sosas de saladar pero de porte más rígido y ramificado. Es una planta iberoafricana que en la península solo vive en los enclaves más áridos del sureste.', NULL, 'Tallos articulados y suculentos, sin hojas; Porte rígido y muy ramificado desde la base; En los suelos más áridos y salinos, casi desnudos', 'Verano y otoño', 'https://observation.org/photos/111149341.jpg', 'Ans Gorter (CC BY-NC-ND 4.0) · observation.org / GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 4 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Anabasis articulata.', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Anabasis', 'NE', 'No localizada en la Lista Roja de la Flora Vascular Española 2008', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 1838, 5568629, NULL, NULL, NULL
