    SELECT 'Esparraguera de gato', 'Asparagus horridus', 'flora', 'Arbusto', 'Matorrales arborescentes de Juniperus spp.', 'No amenazada', 'Esparraguera muy espinosa y densa que se enreda entre el matorral y el sabinar litoral, con cladodios rígidos y punzantes.', NULL, 'Cladodios rígidos y punzantes; Se enreda en el matorral; Frutos negros en otoño', 'Otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Asparagus_stipularis_(detail).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 4 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asparagaceae', 'Asparagus', 'LC', 'No incluida en el LESRPE; acompañante de sabinares y matorrales termófilos (HIC 5210)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 33035, 2768695, NULL, NULL, NULL
    UNION ALL
    SELECT 'Azucena de mar', 'Pancratium maritimum', 'flora', 'Planta bulbosa', 'Dunas y playas del litoral', 'No amenazada', 'Bulbosa de dunas con flores blancas grandes, en forma de trompeta y con una corona membranosa entre los estambres. Se abren al atardecer y despiden un perfume intenso que atrae a polillas nocturnas. Sus hojas son acintadas y de un verde azulado, y a menudo se secan antes de la floración.', NULL, 'Flores blancas en trompeta con una corona membranosa dentro; Se abren al atardecer y huelen intensamente; Hojas acintadas y de verde azulado, saliendo de la arena', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pancratium_maritimum2.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 4 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Amaryllidaceae', 'Pancratium', 'LC', 'No catalogada en la Lista Roja de la Flora Vascular Española 2008 (especie común pero sensible a la degradación de playas)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 6924, 2853283, NULL, NULL, NULL
    UNION ALL
    SELECT 'Romero', 'Rosmarinus officinalis', 'flora', 'Mata aromática', 'Matorral seco y soleado sobre suelos calizos y pedregosos', 'Protegida (LESRPE)', 'Arbusto aromático de hojas estrechas como agujas, verde oscuro por el haz y blanquecinas por el envés, con los bordes enrollados hacia abajo. Florece casi todo el año en azul pálido, y en pleno invierno es una de las pocas fuentes de néctar del matorral.', NULL, 'Hojas como agujas, blancas por debajo; Olor inconfundible al frotar entre los dedos; Flores azul claro repartidas por las ramas casi todo el año', 'Todo el año, con máximo de floración en invierno y primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Rosemary_in_bloom.JPG?width=1280', 'Margalob (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 4 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). Nombre aceptado en EIDOS; Salvia rosmarinus es sinónimo.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Rosmarinus', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 7647, 10902460, NULL, NULL, NULL
    UNION ALL
    SELECT 'Saladilla anual', 'Limonium lobatum', 'flora', 'Hierba', 'Saladares, arenas litorales y suelos salinos secos', 'En Peligro de Extinción', 'Saladilla anual —a diferencia de la mayoría de sus parientes, que son perennes— con una roseta de hojas lobuladas pegada al suelo y tallos alados que rematan en espigas de flores azuladas o violáceas. Sus flores conservan el color al secarse, un truco común en el género.', NULL, 'Roseta basal de hojas con lóbulos redondeados; Tallos con alas o costillas, no cilíndricos; Flores azuladas agrupadas en espiguillas de un solo lado', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_lobatum.jpg?width=1280', 'Sf2000 (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 4 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).; Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Plumbaginaceae', 'Limonium', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 5839, 8419208, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cerrajón', 'Reichardia tingitana', 'flora', 'Hierba', 'Suelos arenosos, ramblas y terrenos removidos en clima cálido y seco', 'No amenazada', 'Hierba anual de aspecto lampiño con capítulos amarillos que llevan en el centro una mancha oscura, casi negra, como un ojo. Al cortar el tallo suelta látex blanco, rasgo compartido con las cerrajas y los dientes de león.', NULL, 'Capítulo amarillo con el centro oscuro, casi negro; Látex blanco al partir el tallo o una hoja; Brácteas anchas y membranosas en el borde, bajo la flor', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Reich-ting-2.jpg?width=1280', 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 4 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Reichardia', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 641, 5385648, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cinomorio', 'Cynomorium coccineum', 'flora', 'Planta parásita', 'Saladares y matorrales halonitrófilos', 'Vulnerable', 'Planta parásita sin clorofila, de aspecto de maza rojiza, que crece sobre las raíces de quenopodiáceas halófilas de los saladares y estepas salinas.', NULL, 'Inflorescencia carnosa rojo-oscura en maza; Sin hojas verdes (parásita); Aparece sobre raíces de plantas halófilas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cynomorium_coccineum_vMH375.jpg?width=1280', 'autor no indicado (Public domain) · Wikimedia Commons', NULL, NULL, 5, NULL, 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Saxifragales', 'Cynomoriaceae', 'Cynomorium', 'NE', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 3790, 7445043, NULL, NULL, NULL
    UNION ALL
    SELECT 'Algazul', 'Mesembryanthemum nodiflorum', 'flora', 'Planta suculenta', 'Saladares, arenas litorales y suelos salinos removidos', 'No amenazada', 'Planta rastrera de hojas cilíndricas y carnosas cubiertas de papilas que brillan al sol como gotas de agua. Acumula sal en sus tejidos y, al secarse en verano, toma tonos rojizos que tiñen el suelo del saladar; se quemaba para obtener sosa, de ahí su nombre.', NULL, 'Hojas gruesas, cilíndricas y con aspecto escarchado; Porte tendido, formando alfombras pegadas al suelo; Vira a rojo intenso al agostarse, en pleno verano', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Mesambryanthemum_nodiflorum.jpg?width=1280', 'Tigerente (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Aizoaceae', 'Mesembryanthemum', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 6174, 3084837, NULL, NULL, NULL
    UNION ALL
    SELECT 'Barrilla pinchosa', 'Salsola kali', 'flora', 'Hierba', 'Arenas y gravas del primer cordón de playa y suelos removidos salinos', 'No amenazada', 'Hierba anual muy ramificada, de hojas carnosas rematadas en un pincho fino, que forma una bola. Al secarse se desprende del suelo y rueda con el viento dispersando las semillas. Coloniza la línea donde el mar deja restos de algas y madera.', NULL, 'Hojas carnosas terminadas en una punta pinchuda; Forma una mata redondeada que rueda al secarse; Tallos con finas líneas rojizas o rosadas', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Salsola_kali_habito.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Salsola', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común litoral)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 7912, 3083957, NULL, NULL, NULL
    UNION ALL
    SELECT 'Zanahoria de mar', 'Pseudorlaya pumila', 'flora', 'Hierba', 'Dunas con céspedes del Malcomietalia', 'No amenazada', 'Pequeña umbelífera anual de las arenas litorales, con umbelas blanco-rosadas y frutos espinosos que se dispersan por la duna.', NULL, 'Umbelas blanco-rosadas; Frutos con espinas; Anual de dunas semifijas', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/475241861/original.jpeg', 'Christoph Moning (CC BY 4.0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Daucus pumilus.', 'Tracheophyta', 'Magnoliopsida', 'Apiales', 'Apiaceae', 'Pseudorlaya', 'LC', 'No incluida en el LESRPE; anual característica del Malcolmietalia (HIC 2230)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 7405, 8241209, NULL, NULL, NULL
    UNION ALL
    SELECT 'Algodonosa', 'Filago mareotica', 'flora', 'Hierba', 'Pastizales anuales sobre arenas y suelos secos y sueltos', 'No amenazada', 'Hierba anual pequeña, cubierta por completo de un fieltro blanco y lanoso que la protege del sol. Sus capítulos son minúsculos y se agrupan en glomérulos apretados en las horquillas del tallo, difíciles de ver si no se busca de cerca.', NULL, 'Toda la planta blanquecina y algodonosa al tacto; Capítulos diminutos apiñados en las bifurcaciones del tallo; Porte erguido de pocos centímetros, ramificado en horquilla', 'Primavera', 'https://observation.org/photos/144643107.jpg', 'Ans Gorter (CC BY-NC-ND 4.0) · observation.org / GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del hábitat de interés comunitario 1510, 6220 según el Atlas y Manual de los Hábitat de España (MITECO, 2005), con presencia confirmada por 3 ocurrencia(s) de GBIF dentro de ese hábitat en este espacio.', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Filago', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 310, 3115813, NULL, NULL, NULL
    UNION ALL
    SELECT 'Bolina', 'Genista umbellata', 'flora', 'Mata', 'Matorrales secos y soleados sobre suelos pobres del sureste ibérico', 'Casi amenazada', 'Mata en forma de bola, densa y ramosa, con ramillas finas y estriadas que hacen la fotosíntesis porque las hojas duran muy poco. En pleno invierno se cubre de flores amarillas agrupadas en el extremo de las ramas, en umbelas apretadas.', NULL, 'Mata redondeada de ramillas verdes, finas y sin espinas; Flores amarillas reunidas al final de la rama, como un ramillete; Hojas diminutas y caedizas: casi siempre parece desnuda', 'Floración de invierno a primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Genista_umbellata.JPG?width=1280', 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Genista', 'NT — Casi amenazada (Lista Roja mundial de la UICN, 2021)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 4925, 8000707, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cuchareta', 'Carrichtera annua', 'flora', 'Hierba', 'Pastizales anuales, eriales y suelos margosos removidos en clima árido', 'No amenazada', 'Crucífera anual de flores blanquecinas con nervios violáceos, inconfundible por su fruto: una vainita corta rematada por una lengüeta plana y curvada que recuerda a una cuchara. Los frutos secos persisten sobre la planta y son la mejor pista para identificarla.', NULL, 'Frutos con una pala plana en el extremo, como cucharillas; Hojas muy divididas, de segmentos estrechos; Planta anual pelosa, de pocos decímetros, en suelo pelado', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Carrichtera_annua2.JPG?width=1280', 'Flora y Vegetación de Lanzarote (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Brassicales', 'Brassicaceae', 'Carrichtera', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 3176, 5375285, NULL, NULL, NULL
    UNION ALL
    SELECT 'Fagonia', 'Fagonia cretica', 'flora', 'Hierba', 'Suelos pedregosos, ramblas y litosuelos de clima árido', 'No amenazada', 'Planta baja y tendida, de tallos angulosos, hojas divididas en tres y estípulas convertidas en espinas finas. Sus flores tienen cinco pétalos de un lila rosado que se abren durante las horas centrales del día. Es de estirpe norteafricana y aquí vive en el extremo de su área.', NULL, 'Porte tendido y desordenado, pegado al suelo; Hojas de tres foliolos con espinas en la base; Flores lila con cinco pétalos bien separados', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fagonia_cretica.jpg?width=1280', 'Retama (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Zygophyllales', 'Zygophyllaceae', 'Fagonia', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE; elemento iberoafricano de interés biogeográfico', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 4561, 6384851, NULL, NULL, NULL
    UNION ALL
    SELECT 'Jarilla de brezo', 'Fumana ericoides', 'flora', 'Mata', 'Matorrales y pastizales pedregosos sobre calizas, en solanas secas', 'No amenazada', 'Matita leñosa de hojas estrechas y punzantes parecidas a las del brezo, de donde le viene el nombre. Sus flores amarillas, de cinco pétalos delicados, se abren por la mañana y pierden los pétalos el mismo día.', NULL, 'Hojas lineares, rígidas y puntiagudas, como agujas cortas; Flores amarillas efímeras, con pétalos arrugados; Mata baja y leñosa en la base, muy ramificada', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fumana_ericoides_Tallos_2010-7-03_ParqueNaturalLagunasdelaMata.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Fumana', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 4652, 8232802, NULL, NULL, NULL
    UNION ALL
    SELECT 'Uña de gato', 'Sedum sediforme', 'flora', 'Planta suculenta', 'Prados calcáreos del Alysso-Sedion albi', 'No amenazada', 'Crasulácea perenne de hojas suculentas puntiagudas y flores amarillo-verdosas, muy extendida por Murcia en repisas rocosas y prados calcáreos; especie característica del hábitat prioritario.', NULL, 'Hojas carnosas puntiagudas; Inflorescencia amarillo pálido; Coloniza repisas y suelos esqueléticos', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sedum_sediforme_hojas.jpg?width=1280', 'autor no indicado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Petrosedum sediforme.; Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí', 'Tracheophyta', 'Magnoliopsida', 'Saxifragales', 'Crassulaceae', 'Sedum', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 8225, 4201784, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cantueso dentado', 'Lavandula dentata', 'flora', 'Mata aromática', 'Tomillares y matorral termomediterráneo', 'No amenazada', 'Lavanda de hojas estrechas con el borde recortado en dientes redondeados, muy aromática. Su espiga violácea remata en un penacho de brácteas del mismo color, más corto que el del cantueso común. Florece durante buena parte del año en clima cálido.', NULL, 'Bordes de la hoja recortados en dientes romos; Penacho de brácteas violetas en lo alto de la espiga; Aroma intenso, entre lavanda y alcanfor', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lavandula_dentata1.jpg?width=1280', 'KENPEI (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 3, NULL, NULL, NULL, 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Lamiaceae', 'Lavandula', 'NE', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 5731, 7307829, NULL, NULL, NULL
    UNION ALL
    SELECT 'Romerina', 'Cistus clusii', 'flora', 'Mata', 'Tomillares y matorral seco sobre calizas y margas', 'No amenazada', 'Jara pequeña de hojas muy estrechas y enrolladas por los bordes, verdes arriba y blancas por debajo, que a distancia recuerdan al romero. Se distingue enseguida al florecer: da grupos de flores blancas de cinco pétalos, mucho mayores que las del romero.', NULL, 'Hojas estrechas enrolladas, blancas por el envés; Flores blancas de cinco pétalos, varias juntas; Sin el olor a romero, aunque se le parezca de lejos', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cistus_clusii_(habitus).jpg?width=1280', 'Hans Hillewaert (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Cistus', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 3610, 7331346, NULL, NULL, NULL
    UNION ALL
    SELECT 'Albaida fina', 'Anthyllis terniflora', 'flora', 'Mata', 'Matorrales áridos y espartales sobre suelos pobres del sureste ibérico', 'No amenazada', 'Mata blanquecina, cubierta de pelos sedosos, con las flores agrupadas de tres en tres a lo largo de las ramas, que es lo que le da nombre. Es una leguminosa del extremo árido del sureste peninsular y del norte de África, adaptada a suelos yesosos y margas.', NULL, 'Flores en grupos de tres, dispuestas a lo largo de la rama; Follaje sedoso y plateado por el pelo tumbado; Cáliz hinchado y peludo que envuelve la flor', 'Floración de invierno a primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Anthyllis_terniflora_kz01.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Anthyllis', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 2192, 5352344, NULL, NULL, NULL
    UNION ALL
    SELECT 'Escobilla', 'Salsola genistoides', 'flora', 'Mata', 'Matorrales halo-nitrófilos', 'No amenazada', 'Mata en forma de escoba, con ramas verdes, largas y erguidas, casi sin hojas, que florece a final de verano. Sus frutos van rodeados de alas membranosas rosadas que la vuelven muy vistosa en otoño. Es un endemismo del sureste ibérico.', NULL, 'Porte en escoba, con ramas verdes largas y erectas; Hojas reducidas casi a escamas; Frutos con alas membranosas rosadas en otoño', 'Verano y otoño', 'https://inaturalist-open-data.s3.amazonaws.com/photos/474144349/original.jpeg', 'Gabriel Dixon (CC0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del hábitat de interés comunitario 1430 según el Atlas y Manual de los Hábitat de España (MITECO, 2005), con presencia confirmada por 3 ocurrencia(s) de GBIF dentro de ese hábitat en este espacio. La cita de GBIF figura como Caroxylon genistoides.', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Salsola', 'NE', 'No incluida en el LESRPE; endemismo ibérico del sureste árido', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, NULL, 3759567, NULL, NULL, NULL
    UNION ALL
    SELECT 'Escarchada', 'Mesembryanthemum crystallinum', 'flora', 'Planta suculenta', 'Suelos salinos y arenosos, taludes y bordes de saladar en clima cálido', 'No amenazada', 'Planta carnosa y tendida cuyas hojas están cubiertas de vesículas transparentes llenas de agua salada: al sol parecen cristales de hielo o gotas de rocío que no se secan. Esas vesículas almacenan la sal que la planta extrae del suelo y le permiten vivir donde el terreno es demasiado salino para otras.', NULL, 'Hojas anchas cubiertas de ampollitas brillantes, como escarcha; Porte rastrero, formando manchas amplias sobre suelo desnudo; Tonos rosados o rojizos al final de su ciclo', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Unk_desert_flower_3.jpg?width=1280', 'Yummifruitbat (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Aizoaceae', 'Mesembryanthemum', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 6172, 3084839, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cebolla albarrana', 'Squilla maritima', 'flora', 'Planta bulbosa', 'Matorrales secos, laderas pedregosas y arenas litorales en clima cálido', 'No amenazada', 'Bulbo enorme, del tamaño de un puño o mayor, que asoma medio enterrado y que en pleno agosto emite un tallo desnudo de más de un metro rematado por una larga espiga de flores blancas. Las hojas, anchas y correosas, aparecen después y desaparecen antes de florecer, así que rara vez se ven flores y hojas a la vez. Es tóxica y también se cita como Drimia maritima o Urginea maritima.', NULL, 'Bulbo grande y visible, asomando entre las piedras; Vara floral alta y desnuda, sin hojas, a final de verano; Roseta de hojas anchas y carnosas en invierno, sin flor', 'Hojas en invierno; floración a final de verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Young_Drimia_maritima%2C_near_Ramon_crater%2C_Israel.jpg?width=1280', 'Someone35 (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Drimia maritima.', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Asparagaceae', 'Squilla', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 9153, 2776790, NULL, NULL, NULL
    UNION ALL
    SELECT 'Orgaza', 'Atriplex glauca', 'flora', 'Mata', 'Matorrales halo-nitrófilos', 'Protegida (LESRPE)', 'Mata baja y extendida, de hojas pequeñas, grisáceas y cubiertas de escamas harinosas que reflejan la luz. Marca los suelos con sal y exceso de nitrógeno, como los antiguos apriscos. Sus frutos van encerrados entre dos valvas endurecidas.', NULL, 'Hojas pequeñas, grises y harinosas al tacto; Porte bajo y muy extendido, casi tendido; Frutos entre dos valvas duras y dentadas', 'Verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/611378691/original.jpg', 'Michael Bakker Paiva (CC BY 4.0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Atriplex', 'LC', 'No incluida en el LESRPE; característica de matorrales halonitrófilos (HIC 1430)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 2639, 7501008, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cerraja fina', 'Sonchus tenerrimus', 'flora', 'Hierba', 'Muros, taludes, cunetas y pies de roca en ambientes secos y alterados', 'No amenazada', 'Cerraja de hojas muy divididas en segmentos estrechos, casi filiformes, que la distinguen de sus parientes de hoja ancha. Brota en cualquier grieta o talud, suelta látex blanco al partirla y florece prácticamente todo el año en clima cálido.', NULL, 'Hojas partidas en segmentos muy estrechos y separados; Látex blanco abundante al romper el tallo; Capítulos amarillo pálido y vilanos sedosos y blancos', 'Casi todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Sonchus_tenerrimus_01.JPG?width=1280', 'Luca Fornasari (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Sonchus', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 9686, 3105768, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cerrillo', 'Hyparrhenia hirta', 'flora', 'Gramínea', 'Laderas secas, ribazos y pastizales sobre suelos pedregosos', 'No amenazada', 'Gramínea perenne que forma matas y espiga en verano, cuando el resto del pastizal ya está agostado. Sus espiguillas van por parejas, cubiertas de pelos rojizos y con aristas retorcidas. Da al paisaje un tono dorado rojizo a final de verano.', NULL, 'Espiguillas peludas agrupadas por parejas; Aristas retorcidas y acodadas; Espiga en verano, cuando lo demás está seco', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hyparrhenia_hirta_Habitus_ValledeAlcudia.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Hyparrhenia', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 10047, 2703243, NULL, NULL, NULL
    UNION ALL
    SELECT 'Barba de chivo', 'Stipa capensis', 'flora', 'Gramínea', 'Pastizales anuales sobre suelos secos y pedregosos', 'No amenazada', 'Gramínea anual que agosta pronto y cubre los claros de matorral de un rubio pajizo. Cada semilla lleva una arista larga y retorcida que gira con los cambios de humedad y va enroscándose hasta clavarla en el suelo. Es la responsable de las «agujas» que se enganchan en los calcetines.', NULL, 'Aristas largas y retorcidas, en espiral al secarse; Planta anual: en verano queda seca y pajiza; Las semillas se clavan en la ropa y el pelaje', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stipa_capensis.JPG?width=1280', 'Juanmadro (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Stipellula capensis.', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Stipa', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 10149, 8315646, NULL, NULL, NULL
    UNION ALL
    SELECT 'Murajes', 'Lysimachia arvensis', 'flora', 'Hierba', 'Cultivos, cunetas, claros y suelos removidos', 'No amenazada', 'Hierbecilla tendida de tallos cuadrangulares y hojas enfrentadas, con flores solitarias que salen de la axila de cada hoja. Las hay de color naranja asalmonado y de color azul intenso, y ambas cierran los pétalos cuando el cielo se nubla, de ahí que se la llamara «hierba del buen tiempo».', NULL, 'Flores solitarias sobre un pedúnculo largo y fino; Tallos de sección cuadrada, tendidos por el suelo; Pétalos que se cierran al nublarse o a media tarde', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/A._arvensis-flor-1.JPG?width=1280', 'Philmarin (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Ericales', 'Primulaceae', 'Lysimachia', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 80964, 8184903, NULL, NULL, NULL
    UNION ALL
    SELECT 'Lastón', 'Brachypodium retusum', 'flora', 'Gramínea', 'Pastizales, claros de matorral y ribazos sobre suelos calizos', 'No amenazada', 'Gramínea perenne y rizomatosa que forma céspedes extensos en los claros del matorral mediterráneo. Sus hojas son cortas, rígidas y de punta roma. Es de las plantas que más rápido rebrota tras un incendio, gracias a sus rizomas subterráneos.', NULL, 'Céspedes extensos y bajos, no matas aisladas; Hojas cortas y rígidas, de punta redondeada; Espiguillas alineadas a un lado de un eje rígido', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Brachypodium_retusum_espiga_seca.jpg?width=1280', 'Pere prlpz (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Presencia documentada por 3 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Brachypodium', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 9931, 5676053, NULL, NULL, NULL
    UNION ALL
    SELECT 'Orgaza', 'Atriplex halimus', 'flora', 'Arbusto', 'Suelos salinos y nitrificados, ramblas y bordes de saladar', 'Protegida (LESRPE)', 'Arbusto de color gris plateado, cubierto de escamas microscópicas que reflejan la luz y ayudan a expulsar sal. Sus hojas son de forma romboidal y algo carnosas. Aguanta suelos que casi ninguna otra planta tolera, por lo que se usa para restaurar terrenos degradados.', NULL, 'Follaje gris plateado, harinoso al tacto; Hojas con forma de rombo o de punta de flecha; Frutos rodeados de dos valvas membranosas', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Atriplex_halimus_kz1.JPG?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Atriplex', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 2712, 3083718, NULL, NULL, NULL
    UNION ALL
    SELECT 'Colleja de arenal', 'Silene ramosissima', 'flora', 'Hierba', 'Dunas con céspedes del Malcolmietalia', 'En Peligro de Extinción', 'Colleja anual muy ramificada desde la base, característica de las dunas semifijas; da nombre a la asociación Triplachno nitentis-Silenetum ramosissimae.', NULL, 'Muy ramificada desde la base; Cáliz inflado con nervios marcados; Anual de vida corta', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Silene_ramosissima_2.jpg?width=1280', 'bymamo (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Caryophyllaceae', 'Silene', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 8435, 5584675, NULL, NULL, NULL
    UNION ALL
    SELECT 'Rubia marina', 'Crucianella maritima', 'flora', 'Mata', 'Dunas y arenas litorales estabilizadas', 'Sensible a la alteración de su hábitat', 'Matita rígida de las arenas costeras, con las hojas dispuestas en verticilos de cuatro que envuelven el tallo formando una columna geométrica de un verde glauco. Sus flores amarillentas se abren en espigas terminales apretadas, y sus tallos leñosos fijan la arena a su alrededor.', NULL, 'Hojas en anillos de cuatro alrededor del tallo, muy regulares; Aspecto rígido y azulado, casi de plástico, sobre arena; Espigas terminales de flores pequeñas y amarillentas', 'Primavera y principio de verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Crucianella_maritima_1.JPG?width=1280', 'Gideon Pisanty (Gidip) גדעון פיזנטי (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Gentianales', 'Rubiaceae', 'Crucianella', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 3764, 5336649, NULL, NULL, NULL
    UNION ALL
    SELECT 'Acebuche', 'Olea europaea subsp. europaea', 'flora', 'Árbol', 'Matorral alto, laderas secas y barrancos del piso más cálido', 'No amenazada', 'El acebuche es el olivo silvestre: mismo árbol, sin siglos de selección. Tiene las hojas más pequeñas y duras, las ramas jóvenes a menudo espinosas y aceitunas diminutas. Forma matorrales altos y es el árbol característico de las laderas cálidas mediterráneas.', NULL, 'Hojas pequeñas, verdes arriba y plateadas por debajo; Ramillas jóvenes rígidas y a veces espinosas; Aceitunas muy pequeñas, de poco más de un centímetro', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ullastre_vell.JPG?width=1280', 'Antoni Salvà (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO). La cita de GBIF figura como Olea europaea. Nombre aceptado en EIDOS; Olea europaea var. sylvestris es sinónimo.', 'Tracheophyta', 'Magnoliopsida', 'Lamiales', 'Oleaceae', 'Olea', 'LC', 'No catalogada en la Lista Roja de la Flora Vascular Española 2008', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 6644, 5415040, NULL, NULL, NULL
    UNION ALL
    SELECT 'Albaida', 'Anthyllis cytisoides', 'flora', 'Mata', 'Matorral seco y soleado sobre margas y suelos pobres', 'Protegida (LESRPE)', 'Mata de aspecto blanquecino por la fina pelusa que cubre hojas y tallos, un recurso frente al sol y la sequía. En primavera se llena de espigas de flores amarillas que atraen a muchos insectos. Es una de las leguminosas que primero coloniza laderas degradadas y taludes.', NULL, 'Aspecto grisáceo y aterciopelado al tacto; Flores amarillas pequeñas en espigas apretadas; Hojas divididas en tres, la del centro más larga', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Anthyllis_cytisoides.JPG?width=1280', 'Ximenex (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Anthyllis', 'No evaluada específicamente en la Lista Roja mundial de la UICN (especie muy común)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 2186, 5352466, NULL, NULL, NULL
    UNION ALL
    SELECT 'Boja negra', 'Artemisia barrelieri', 'flora', 'Mata aromática', 'Matorrales halo-nitrófilos', 'No amenazada', 'Mata aromática grisácea de las bojas del sureste árido, colonizadora de suelos alterados, bordes de camino y matorrales nitrificados.', NULL, 'Olor aromático fuerte al frotar; Follaje gris-plateado; Indica suelos alterados', 'Otoño', 'https://inaturalist-open-data.s3.amazonaws.com/photos/173279674/original.jpeg', 'Yamil J.R (CC0) · GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del hábitat de interés comunitario 1430 según el Atlas y Manual de los Hábitat de España (MITECO, 2005), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de ese hábitat en este espacio.', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Artemisia', 'NE', 'No incluida en el LESRPE; característica de matorrales halonitrófilos (HIC 1430)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 9913, 3120786, NULL, NULL, NULL
    UNION ALL
    SELECT 'Acelguilla espinosa', 'Limonium echioides', 'flora', 'Hierba', 'Pastizales secos, suelos margosos y salinos en clima árido', 'No amenazada', 'Saladilla anual pequeña, con una roseta de hojas ásperas al tacto y tallos ramificados en zigzag que llevan las flores en espiguillas cortas. Las flores, blanquecinas o violáceas, conservan el cáliz seco y papiráceo mucho después de marchitarse.', NULL, 'Hojas de la roseta ásperas, con pelillos duros; Tallos en zigzag, con ramas divaricadas; Cálices secos y papiráceos persistiendo tras la flor', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_echioides233.JPG?width=1280', 'Nanosanchez (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Plumbaginaceae', 'Limonium', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 5805, 4090024, NULL, NULL, NULL
    UNION ALL
    SELECT 'Campanica', 'Convolvulus althaeoides', 'flora', 'Hierba', 'Ribazos, cunetas, cultivos y claros de matorral', 'No amenazada', 'Correhuela trepadora de flores rosadas grandes y llamativas, con hojas muy variables: las de abajo casi enteras y las de arriba profundamente divididas y plateadas. Se enreda en la vegetación de ribazos y márgenes.', NULL, 'Flores rosa intenso en embudo, grandes y vistosas; Hojas superiores muy recortadas y de aspecto plateado; Tallos volubles que se enredan en otras plantas', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Convolvulus_althaeoides_1.JPG?width=1280', 'User:Xemenendura (CC BY-SA 2.1 es) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 2 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Solanales', 'Convolvulaceae', 'Convolvulus', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 3692, 2928400, NULL, NULL, NULL
    UNION ALL
    SELECT 'Siempreviva de Cosson', 'Limonium cossonianum', 'flora', 'Hierba', 'Saladares, acantilados costeros y suelos salinos margosos', 'Especies de interés especial', 'Siempreviva de roseta basal de hojas espatuladas y tallos ramificados que sostienen espiguillas de flores diminutas de color lila. Los cálices secos y papiráceos permanecen en la planta hasta el invierno siguiente, dando al saladar un tono pajizo persistente.', NULL, 'Roseta basal de hojas anchas y espatuladas; Ramificación en zigzag, muy abierta; Cálices secos que persisten meses tras florecer', 'Verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Limonium_cossonianum.jpg?width=1280', 'Nanosanchez (CC0) · Wikimedia Commons', NULL, NULL, 3, NULL, 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Plumbaginaceae', 'Limonium', 'NE', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 5761, 7297983, NULL, NULL, NULL
    UNION ALL
    SELECT 'Sosa blanca', 'Suaeda maritima', 'flora', 'Hierba', 'Marismas, saladares y orillas de aguas salobres', 'Sensible a la alteración de su hábitat', 'Hierba anual de hojas cilíndricas y carnosas que crece en los suelos más encharcados y salinos del saladar, donde el agua sube y baja. Al final del ciclo toma tonos rojizos o purpúreos que delatan su presencia a distancia.', NULL, 'Hojas carnosas, cilíndricas y de punta roma; Flores diminutas y verdosas en la axila de las hojas; Coloración rojiza al final del verano, en suelo salino húmedo', 'Verano y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Suaeda_maritima_01_by_Line1.JPG?width=1280', 'Liné1 (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Amaranthaceae', 'Suaeda', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 8514, 3083541, NULL, NULL, NULL
    UNION ALL
    SELECT 'Albohol', 'Frankenia pulverulenta', 'flora', 'Hierba', 'Saladares, depresiones salinas y suelos arcillosos que se encharcan en invierno', 'Vulnerable', 'Hierba anual tendida, de hojas pequeñas y enfrentadas con el envés cubierto de un polvillo blanco de sal que la planta expulsa por glándulas propias. Forma alfombras bajas y ralas en los claros del saladar, con flores rosadas de cinco pétalos diminutos.', NULL, 'Envés de las hojas blanquecino, como espolvoreado; Porte tendido y menudo, pegado al suelo salino; Flores rosadas muy pequeñas, en la axila de las hojas', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Frankenia_pulverulenta_kz2.jpg?width=1280', 'Krzysztof Ziarnek, Kenraiz (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Frankeniaceae', 'Frankenia', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 4619, 2874692, NULL, NULL, NULL
    UNION ALL
    SELECT 'Taraje', 'Tamarix gallica', 'flora', 'Árbol', 'Ramblas, cauces salinos, márgenes de saladar y arenas húmedas', 'Especies de interés especial', 'Arbolillo de porte ligero y ramas colgantes cubiertas de hojas escamosas diminutas, con un follaje que de lejos parece humo verde. Tolera la sal como pocos árboles: la excreta por sus hojas, y sus espigas rosadas de flores minúsculas cubren la copa en primavera.', NULL, 'Hojas escamosas de un par de milímetros, pegadas a la ramilla; Ramas finas y péndulas, de aspecto plumoso; Espigas densas de florecillas rosadas o blanquecinas', 'Floración de primavera a verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tamarix_gallica_-_Villa_Taranto_(Verbania)_-_DSC03778.JPG?width=1280', 'Daderot (Public domain) · Wikimedia Commons', NULL, NULL, 1, NULL, 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Tamaricaceae', 'Tamarix', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'ANEXO XII. Especies a las que se refiere la disposición adicional tercera (otras especies forestales importantes para la selvicultura en España) (Real Decreto 289/2003, de 7 de marzo, sobre la comercialización de los materiales forestales de reproducción (Catálogo Nacional de Materiales de Base))', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 8551, 8380575, NULL, NULL, NULL
    UNION ALL
    SELECT 'Grama de arena', 'Ammochloa palaestina', 'flora', 'Gramínea', 'Arenas litorales y suelos sueltos y secos', 'Especies de interés especial', 'Gramínea anual enana que forma una mata apretada a ras de suelo, con la inflorescencia reducida a una cabezuela compacta casi sin tallo, medio escondida entre las hojas. Vive en arenas móviles, donde su ciclo relámpago aprovecha la humedad de las lluvias.', NULL, 'Inflorescencia en cabezuela apretada, casi sentada sobre la mata; Planta enana, de pocos centímetros, sobre arena suelta; Hojas cortas y rígidas, agrupadas en la base', 'Primavera', NULL, NULL, NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Ammochloa', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2013)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 9756, 4106283, NULL, NULL, NULL
    UNION ALL
    SELECT 'Ajo porro', 'Allium subvillosum', 'flora', 'Planta bulbosa', 'Arenas litorales, pastizales secos y claros de matorral', 'En Peligro de Extinción', 'Ajo silvestre de flores blancas agrupadas en una umbela laxa sobre un tallo fino, con las hojas estrechas y con el borde y el nervio ligeramente pelosos. Como todos los ajos, delata su identidad en cuanto se estruja una hoja.', NULL, 'Umbela de flores blancas con nervio verdoso en cada pétalo; Hojas estrechas con pelillos en el margen; Olor claro a ajo al frotar las hojas o el bulbo', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Allium_subvillosum.JPG?width=1280', 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Liliopsida', 'Asparagales', 'Amaryllidaceae', 'Allium', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 2031, 2857317, NULL, NULL, NULL
    UNION ALL
    SELECT 'Algarrobo', 'Ceratonia siliqua', 'flora', 'Árbol', 'Laderas cálidas, antiguos cultivos y matorral del piso termomediterráneo', 'Protegida (LESRPE)', 'Árbol perennifolio de copa densa y hojas compuestas con foliolos redondeados y lustrosos. Florece en otoño directamente sobre el tronco y las ramas viejas. Sus vainas pardas y dulces, las algarrobas, se han usado durante siglos como pienso y alimento.', NULL, 'Hojas compuestas de foliolos redondos y brillantes; Flores nacidas directamente del tronco y las ramas gruesas; Vainas pardas y aplanadas colgando del árbol', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ceratonia_siliqua_Keciboynuzu_1370984_Nevit.jpg?width=1280', 'Nevit Dilmen (talk) (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Fabales', 'Fabaceae', 'Ceratonia', 'LC (Preocupación menor) (evaluación UICN 2017)', 'ANEXO I. 2) Lista de taxones forestales para conservación ex situ (Real Decreto 159/2022, de 1 de marzo, sobre conservación de los recursos genéticos foresta…)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 3422, 5356354, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cerraja gaditana', 'Reichardia gaditana', 'flora', 'Hierba', 'Arenas litorales, suelos salinos y eriales cercanos a la costa', 'No amenazada', 'Pariente cercana del cerrajón, anual y de hojas carnosas abrazadas al tallo, con capítulos amarillos y látex blanco. Es propia de suelos arenosos y algo salinos del suroeste y del sureste peninsular.', NULL, 'Hojas basales carnosas, con dientes anchos y triangulares; Capítulos amarillos con brácteas de borde membranoso; Látex blanco al partir cualquier parte de la planta', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Reichardia_gaditana_2.JPG?width=1280', 'Xemenendura (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Asterales', 'Asteraceae', 'Reichardia', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 638, 5385653, NULL, NULL, NULL
    UNION ALL
    SELECT 'Eslizón ibérico', 'Chalcides bedriagai', 'fauna', 'Reptil', 'Matorral termomediterráneo semiárido', 'Vulnerable', 'Eslizón de cuerpo cilíndrico y brillante, con las patas tan reducidas que apenas se usan: se desplaza reptando y buceando entre la arena y la hojarasca. Su dorso, dorado o bronceado, lleva hileras de ocelos oscuros con el centro claro.', NULL, 'Patas diminutas, casi inútiles para caminar; Cuerpo cilíndrico y muy brillante, como pulido; Hileras de ocelos oscuros de centro claro en el dorso', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chalcides_bedriagai_01_by-dpc.jpg?width=1280', 'David Perez (CC BY 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Chordata', 'Reptilia', 'Squamata', 'Scincidae', 'Chalcides', 'LC', 'LESRPE; Directiva Hábitats 92/43/CEE, Anexo IV', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 10827, 8974077, NULL, NULL, NULL
    UNION ALL
    SELECT 'Helianthemum viscarium', 'Helianthemum viscarium', 'flora', 'Mata', 'Tomillares y matorral raso sobre margas y suelos yesosos', 'No amenazada', 'Jarilla pequeña y pegajosa, con hojas estrechas y tallos cubiertos de pelos glandulosos que retienen el polvo. Sus flores amarillas duran apenas unas horas y se renuevan cada día. Es un endemismo del sureste ibérico ligado a suelos margosos.', NULL, 'Tallos pegajosos, con polvo y arena adheridos; Flores amarillas efímeras, de un solo día; Sobre margas y yesos, en terreno claro', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/384325778/original.jpg', 'anarkis (CC BY-NC 4.0) · GBIF/iNaturalist', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Malvales', 'Cistaceae', 'Helianthemum', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'Sin figura de protección nacional específica registrada en EIDOS', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 5103, 7331463, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cardo mancaperros', 'Eryngium ilicifolium', 'flora', 'Hierba', 'Pastizales secos, eriales y suelos margosos pisoteados', 'No amenazada', 'Cardo corredor anual, muy espinoso y rígido, con hojas duras parecidas a las de la encina —de ahí el nombre— y cabezuelas espinosas azuladas rodeadas de brácteas punzantes. Al secarse se vuelve leñoso y persiste todo el verano pinchando a quien pase.', NULL, 'Hojas rígidas y espinosas, recortadas como las de la encina; Cabezuelas con brácteas largas y punzantes en estrella; Tonos azulados en las brácteas durante la floración', 'Primavera y verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Eryngium_ilicifolium_InflorescenceCloseup2_DehesaBoyaldePuertollano.jpg?width=1280', 'Javier martin (Public domain) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).; Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí', 'Tracheophyta', 'Magnoliopsida', 'Apiales', 'Apiaceae', 'Eryngium', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 4406, 3630524, NULL, NULL, NULL
    UNION ALL
    SELECT 'Cosco', 'Aizoanthemopsis hispanica', 'flora', 'Planta suculenta', 'Suelos salinos y margosos desnudos, en depresiones áridas', 'No amenazada', 'Anual carnosa y tendida, cubierta de papilas que le dan aspecto áspero y blanquecino, con flores pequeñas sin pétalos que se abren estrelladas al sol. Es una planta de los suelos más pobres y salinos, donde forma manchas dispersas sobre el barro desnudo.', NULL, 'Ramas carnosas y tendidas, ásperas y grisáceas; Flores sin pétalos, con sépalos que se abren en estrella; Crece sobre suelo desnudo, salino o margoso', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Aizoon_hispanicum_2b.JPG?width=1280', 'Ghislain118 https://www.fleurs-des-montagnes.net (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Caryophyllales', 'Aizoaceae', 'Aizoanthemopsis', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 1811, 9819723, NULL, NULL, NULL
    UNION ALL
    SELECT 'Crásula enana', 'Crassula tillaea', 'flora', 'Planta suculenta', 'Claros arenosos y suelos someros que se encharcan brevemente en invierno', 'No amenazada', 'Una de las plantas con flor más pequeñas de la península: apenas un centímetro de tallos carnosos con hojitas apretadas en pares, que al madurar se tiñen de rojo intenso y colorean el suelo. Hay que agacharse mucho para verla, pero cuando abunda pinta manchas rojizas inconfundibles.', NULL, 'Planta minúscula, de menos de dos centímetros; Hojas carnosas opuestas y apretadas a lo largo del tallo; Vira a rojo intenso al madurar, tiñendo el suelo', 'Final de invierno y primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Crassula_connata.jpg?width=1280', 'Mike (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Saxifragales', 'Crassulaceae', 'Crassula', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2013)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 3849, 5362055, NULL, NULL, NULL
    UNION ALL
    SELECT 'Erodio', 'Erodium sanguis-christi', 'flora', 'Hierba', 'Litosuelos y pastizales abiertos', 'Especies de interés especial', 'Pequeña geraniácea anual de suelos abiertos y pedregosos, de floración temprana en el piso termomediterráneo semiárido.', NULL, 'Flores rosadas pequeñas; Fruto con pico alargado característico de Erodium; Anual de suelos pedregosos', 'Primavera', 'https://inaturalist-open-data.s3.amazonaws.com/photos/642301345/original.jpg', 'Laia Lahoz (CC BY-NC 4.0) · iNaturalist/GBIF', NULL, NULL, 4, NULL, 3, '{"categoria":"Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Geraniales', 'Geraniaceae', 'Erodium', 'NE', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'Especies de interés especial (Decreto n.º 50/2003, de 30 de mayo por el que se crea el Catálogo Regional de Flora Silvestre Protegida de la Región de Murcia y se dictan Normas para el aprovechamiento de diversas especies forestales.)', NULL, 9835, 7268491, NULL, NULL, NULL
    UNION ALL
    SELECT 'Grama salada', 'Sphenopus divaricatus', 'flora', 'Gramínea', 'Saladares, depresiones salinas y suelos arcillosos con sal', 'No amenazada', 'Gramínea anual delicada, de tallos finísimos y panícula muy abierta con las ramas separadas casi en ángulo recto, que en conjunto parece una nube. Es una de las pocas gramíneas capaces de completar su ciclo en los suelos salinos del saladar.', NULL, 'Panícula muy abierta, con ramas separadas en ángulo recto; Planta anual grácil, de tallos capilares; Espiguillas diminutas en el extremo de las ramas', 'Primavera', 'https://observation.org/photos/125538681.jpg', 'Humedales de Navarra (CC BY-NC-ND 4.0) · observation.org / GBIF', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie característica del hábitat de interés comunitario  según el Atlas y Manual de los Hábitat de España (MITECO, 2005), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de ese hábitat en este espacio.; Atlas y Manual de los Hábitats de España (MITECO, 2005): especie característica de alguno de los HIC cartografiados aquí', 'Tracheophyta', 'Liliopsida', 'Poales', 'Poaceae', 'Sphenopus', 'No evaluada en la Lista Roja mundial de la UICN', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 10143, 4153196, NULL, NULL, NULL
    UNION ALL
    SELECT 'Canadillo', 'Ephedra fragilis', 'flora', 'Arbusto', 'Roquedos, matorral seco y pie de acantilado en clima cálido', 'Protegida (LESRPE)', 'Arbusto de aspecto extraño: un manojo de tallos verdes, articulados y colgantes, casi sin hojas, que se quiebran con facilidad por los nudos. No es una planta con flores, sino un pariente lejano de las coníferas; sus semillas van envueltas en una cubierta roja y carnosa.', NULL, 'Tallos verdes articulados que se rompen por los nudos; Sin hojas visibles, solo escamas en cada nudo; Frutos rojos carnosos con una semilla dentro', 'Primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ephedra_fragilis_3.JPG?width=1280', 'User:falconaumanni (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Gnetopsida', 'Ephedrales', 'Ephedraceae', 'Ephedra', 'LC (Preocupación menor)', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 4308, 2653414, NULL, NULL, NULL
    UNION ALL
    SELECT 'Oroval', 'Withania frutescens', 'flora', 'Arbusto', 'Matorral cálido, roquedos y ramblas de clima muy seco', 'Protegida (LESRPE)', 'Arbusto de la familia del tomate y la belladona, con hojas ovaladas algo carnosas y flores verdosas discretas. Los frutos son bayas rojas y brillantes envueltas en el cáliz. Es una especie de raíz norteafricana que en la península solo vive en los rincones más cálidos del sureste.', NULL, 'Bayas rojas pequeñas asomando del cáliz; Hojas ovales, algo carnosas y de verde apagado; Flores verde amarillentas, poco vistosas', 'Primavera y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Withania_frutescens0176.jpg?width=1280', 'Nanosanchez (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie incluida en catálogo o anexo oficial de protección (EIDOS, IEPNB), con presencia confirmada por 1 ocurrencia(s) de GBIF dentro de los polígonos de hábitat de este espacio (cartografía del Atlas de Hábitat 2005, MITECO).', 'Tracheophyta', 'Magnoliopsida', 'Solanales', 'Solanaceae', 'Withania', 'No evaluada específicamente en la Lista Roja mundial de la UICN', 'No incluida en la Lista Roja de la Flora Vascular Española (2008) ni en el LESRPE; elemento iberoafricano de interés biogeográfico', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 9438, 3801152, NULL, NULL, NULL
    UNION ALL
    SELECT 'Charrancito común', 'Sternula albifrons', 'fauna', 'Ave marina', 'Playas de arena y grava, salinas y lagunas costeras', 'Vulnerable', 'El más pequeño de los charranes europeos, con la frente blanca y el pico amarillo de punta negra. Cría directamente sobre la arena o la grava, en nidos que son poco más que un hoyo, lo que lo hace muy sensible al tránsito de personas en las playas.', NULL, 'Frente blanca que contrasta con el capirote negro; Pico amarillo con la punta negra; Se ciñe sobre el agua antes de zambullirse en picado', 'Primavera y verano (estival)', 'https://commons.wikimedia.org/wiki/Special:FilePath/Little_Tern_6820C.jpg?width=1280', 'Little_Tern_6820.jpg: Alnus derivative work: Osado (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES6200010 y ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.', 'Chordata', 'Aves', 'Charadriiformes', 'Laridae', 'Sternula', 'LC', 'LESRPE (Listado de Especies Silvestres en Régimen de Protección Especial); Directiva Aves 2009/147/CE, Anexo I', 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 14084, NULL, 'ES0000507', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Alca común', 'Alca torda', 'fauna', 'Ave marina', 'Mar abierto y aguas costeras fuera de la época de cría', 'Vulnerable', 'Ave marina compacta, negra por arriba y blanca por debajo, con un pico grueso y comprimido lateralmente cruzado por una línea blanca. Vuela bajo y rápido, rozando el agua, y bucea propulsándose con las alas para perseguir peces pequeños.', NULL, 'Pico grueso y aplanado de lado, con una raya blanca vertical; Vuelo rápido a ras de agua, con aleteo rígido; Se zambulle desde la superficie, sin lanzarse desde el aire', 'Invierno', 'https://commons.wikimedia.org/wiki/Special:FilePath/Razorbill_iceland.JPG?width=1280', 'autor no indicado (Public domain) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 36 ocurrencias de GBIF dentro de este espacio.', 'Chordata', 'Aves', 'Charadriiformes', 'Alcidae', 'Alca', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2021)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 14089, NULL, 'ES0000507', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Pardela cenicienta mediterránea', 'Calonectris diomedea', 'fauna', 'Ave marina', 'Mar abierto; cría en islotes e islas del Mediterráneo', 'Vulnerable (Región de Murcia)', 'Pardela grande de dorso pardo ceniciento y vientre blanco, con pico amarillento, que planea largamente sobre las olas alternando ascensos y descensos casi sin batir las alas. Cría en colonias en islotes rocosos y se acerca a ellos de noche, con reclamos que recuerdan a un llanto.', NULL, 'Vuelo planeado en arcos largos, casi sin aletear; Dorso pardo ceniciento sin capucha oscura marcada; Pico amarillento con la punta oscura', 'De primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/CorysShearwaterBottom.jpg?width=1280', 'TomAllmendinger (CC BY 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.', 'Chordata', 'Aves', 'Procellariiformes', 'Procellariidae', 'Calonectris', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'Anexo IV (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007)', 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 11166, NULL, 'ES0000507', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Fumarel común', 'Chlidonias niger', 'fauna', 'Ave acuática', 'Humedales, lagunas y costas someras durante el paso migratorio', 'En peligro de extinción', 'Charrán pequeño y oscuro que en plumaje nupcial es casi negro con las alas grises, y en invierno gris y blanco con una mancha oscura en el lado del pecho. No se zambulle como los charranes marinos: vuela errático sobre el agua y picotea la superficie al pasar.', NULL, 'Vuelo errático y buceante sobre el agua, sin zambullirse; Mancha oscura a los lados del pecho en plumaje de invierno; Cola poco ahorquillada, más corta que la de los charranes', 'Pasos de primavera y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Chlidonias_niger.jpg?width=1280', 'USGov (Public domain) · Wikimedia Commons', NULL, NULL, 5, '{"categoria":"CEEA: En peligro de extinción (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"CEEA: En peligro de extinción (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.', 'Chordata', 'Aves', 'Charadriiformes', 'Laridae', 'Chlidonias', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'CEEA: En peligro de extinción (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011) · Anexo IV (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 14086, NULL, 'ES0000507', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Paíño europeo', 'Hydrobates pelagicus', 'fauna', 'Ave marina', 'Mar abierto; cría en grietas y cuevas de islotes', 'Anexo I', 'El ave marina más pequeña del Mediterráneo, apenas del tamaño de un gorrión, negruzca con una banda blanca muy marcada en la rabadilla. Revolotea a ras de agua como una mariposa, con las patas colgando y rozando la superficie.', NULL, 'Tamaño diminuto, negruzco, con obispillo blanco evidente; Vuelo aleteado y errático, casi pegado al agua; Patas colgando que rozan la superficie al alimentarse', 'Sobre todo de primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Hydrobates_pelagicus.jpg?width=1280', 'Júlio Reis (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.', 'Chordata', 'Aves', 'Procellariiformes', 'Hydrobatidae', 'Hydrobates', 'VU — Vulnerable (Lista Roja mundial de la UICN, 1992)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 11953, NULL, 'ES0000507', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Gaviota de Audouin', 'Larus audouinii', 'fauna', 'Ave marina', 'Islotes y costas mediterráneas; pesca en mar abierto cerca de la orilla', 'Anexo II. Lista de especies en peligro o amenazadas.', 'Gaviota mediterránea de tamaño medio, elegante y de aspecto más «limpio» que la patiamarilla, con el pico rojo coral anillado de negro y las patas verdosas oscuras. Pesca al vuelo rozando el agua, sobre todo de noche y de madrugada. Cría en colonias muy concentradas en islotes y salinas.', NULL, 'Pico rojo coral con una banda negra cerca de la punta; Patas verde oscuro, no amarillas; Ojo oscuro que le da expresión suave', 'Todo el año, con concentraciones en verano', 'https://inaturalist-open-data.s3.amazonaws.com/photos/611415320/original.jpg', 'Michael Bakker Paiva (CC BY 4.0) · GBIF', NULL, NULL, 4, '{"categoria":"Catálogo Español de Especies Amenazadas (CEEA): Vulnerable","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 4, '{"categoria":"Catálogo Español de Especies Amenazadas (CEEA): Vulnerable","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.', 'Chordata', 'Aves', NULL, NULL, 'Larus', 'VU (Vulnerable)', 'Catálogo Español de Especies Amenazadas (CEEA): Vulnerable; Ley 42/2007, Anexo IV', 'Vulnerable (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 14053, NULL, 'ES0000507', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Gaviota sombría', 'Larus fuscus', 'fauna', 'Ave marina', 'Costas, puertos, playas y vertederos, sobre todo en invierno', 'Anexo II', 'Gaviota grande de dorso gris oscuro o casi negro y patas amarillas, que cría en el norte de Europa e inverna en gran número en las costas ibéricas. Se mezcla con la patiamarilla, de la que se distingue por el manto mucho más oscuro y el porte algo más estilizado.', NULL, 'Manto gris pizarra oscuro, mucho más que en la patiamarilla; Patas amarillas y pico amarillo con mancha roja; Presente sobre todo en invierno, en bandos mixtos', 'Otoño e invierno', 'https://commons.wikimedia.org/wiki/Special:FilePath/Larus-fuscus-taxbox.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 11 ocurrencias de GBIF dentro de este espacio.', 'Chordata', 'Aves', 'Charadriiformes', 'Laridae', 'Larus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 14057, NULL, 'ES0000507', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Gaviota cabecinegra', 'Larus melanocephalus', 'fauna', 'Ave marina', 'Costas, playas, salinas y lagunas litorales', 'Anexo II. Lista de especies en peligro o amenazadas.', 'Gaviota mediana de alas blanquecinas sin puntas negras, pico rojo coral y capucha negra completa en primavera. En vuelo destaca por sus primarias sin marcas oscuras, un rasgo que la separa de la reidora aun de lejos.', NULL, 'Alas blancas sin puntas negras, muy pálidas en vuelo; Pico rojo intenso y grueso, con anillo ocular blanco; Capucha negra completa en primavera; mancha en la oreja en invierno', 'Otoño e invierno, con paso en primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Larus_melanocephalus_aka_Mediterranean_Gull_rare_guest_in_Sweden2.jpg?width=1280', 'Martin Olsson (mnemo on en/sv wikipedia and commons, martin@minimum… (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.', 'Chordata', 'Aves', 'Charadriiformes', 'Laridae', 'Larus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011) · Anexo IV (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 14050, NULL, 'ES0000507', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Gaviota reidora', 'Chroicocephalus ridibundus', 'fauna', 'Ave marina', 'Costas, salinas, embalses, ríos y campos de cultivo inundados', 'Anexo III', 'Gaviota pequeña y ágil, muy común en invierno tierra adentro. En verano lleva la cabeza cubierta por una capucha de color chocolate; en invierno solo le queda una mancha oscura tras el ojo. En vuelo enseña una cuña blanca inconfundible en el borde delantero del ala.', NULL, 'Cuña blanca en el filo delantero del ala, visible en vuelo; En invierno, una mancha oscura como un auricular tras el ojo; Pico y patas rojo oscuro', 'Otoño e invierno', 'https://inaturalist-open-data.s3.amazonaws.com/photos/605325270/original.jpg', 'lalaia (CC BY 4.0) · GBIF', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 144 ocurrencias de GBIF dentro de este espacio. La lista oficial la cita como Larus ridibundus; EIDOS (IEPNB) acepta Chroicocephalus ridibundus.', 'Chordata', 'Aves', NULL, NULL, 'Chroicocephalus', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 16356, NULL, 'ES0000507', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Alcatraz atlántico', 'Morus bassanus', 'fauna', 'Ave marina', 'Mar abierto y aguas costeras en invierno', 'Protegida (LESRPE)', 'Ave marina grande y blanca con las puntas de las alas negras y la cabeza teñida de amarillo, de silueta afilada como una lanza. Pesca lanzándose en picado desde decenas de metros y entrando en el agua como un arpón, en zambullidas que se ven desde la costa.', NULL, 'Silueta blanca en cruz, con las puntas de las alas negras; Zambullidas verticales espectaculares desde gran altura; Cabeza y cuello con tinte amarillento en los adultos', 'Otoño e invierno', 'https://commons.wikimedia.org/wiki/Special:FilePath/Morus_bassanus_adu.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 48 ocurrencias de GBIF dentro de este espacio.', 'Chordata', 'Aves', 'Suliformes', 'Sulidae', 'Morus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 14031, NULL, 'ES0000507', 1, '{"tipos":["invernante"],"etiqueta":"Invernante: pasa aquí el invierno","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Págalo parásito', 'Stercorarius parasiticus', 'fauna', 'Ave marina', 'Mar abierto y aguas costeras durante los pasos migratorios', 'Protegida (LESRPE)', 'Ave marina de vuelo rápido y ágil, con aspecto de gaviota estilizada y las dos plumas centrales de la cola alargadas en punta. Se alimenta persiguiendo a charranes y gaviotas hasta obligarlos a soltar la presa, un comportamiento llamado cleptoparasitismo.', NULL, 'Persigue a otras aves marinas en vuelo, acosándolas; Dos plumas centrales de la cola alargadas y puntiagudas; Manchas blancas en la base de las primarias, visibles en vuelo', 'Pasos de primavera y otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Arctic_skua_(Stercorarius_parasiticus)_on_an_ice_floe%2C_Svalbard.jpg?width=1280', 'AWeith (CC BY-SA 4.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.', 'Chordata', 'Aves', 'Charadriiformes', 'Stercorariidae', 'Stercorarius', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 14042, NULL, 'ES0000507', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Págalo pomarino', 'Stercorarius pomarinus', 'fauna', 'Ave marina', 'Mar abierto, en paso migratorio frente a las costas', 'Protegida (LESRPE)', 'Págalo grande y robusto, de pecho ancho y vuelo potente, con las plumas centrales de la cola ensanchadas y retorcidas en cuchara cuando es adulto. Como sus parientes, roba comida a otras aves marinas y sigue a los barcos de pesca.', NULL, 'Plumas centrales de la cola anchas y retorcidas en el adulto; Cuerpo pesado y pecho ancho, más que en el págalo parásito; Vuelo directo y potente, con aleteo profundo', 'Pasos de otoño y primavera', 'https://commons.wikimedia.org/wiki/Special:FilePath/Stercorarius_pomarinusPCCA20070623-3985B.jpg?width=1280', 'Patrick Coin (Patrick Coin) (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.', 'Chordata', 'Aves', 'Charadriiformes', 'Stercorariidae', 'Stercorarius', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 14041, NULL, 'ES0000507', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
