    SELECT 'Charrán común', 'Sterna hirundo', 'fauna', 'Ave marina', 'Costas, salinas, deltas y lagunas litorales', 'Sensible a la alteración de su hábitat', 'Charrán esbelto de alas estrechas y cola muy ahorquillada, gris pálido por encima, con capirote negro y pico rojo de punta oscura. Pesca cerniéndose sobre el agua y lanzándose en picado corto, y su reclamo áspero delata las colonias a distancia.', NULL, 'Pico rojo con la punta negra en primavera y verano; Cola muy ahorquillada, con las plumas externas largas; Se cierne y se lanza en picado corto sobre el agua', 'De primavera a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Charr%C3%A1n_Com%C3%BAn_(Sterna_hirundo_hirundo)_in_Canary_Islands.jpg?width=1280', 'Juan Emilio from Las Palmas de Gran Canaria, España (CC BY-SA 2.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 3, '{"categoria":"Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)","ambito":"autonómico","origen":"murciaStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.', 'Chordata', 'Aves', 'Charadriiformes', 'Laridae', 'Sterna', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011) · Anexo IV (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007)', 'Especies de interés especial (Ley 7/1995, de 21 de abril, de la fauna silvestre, caza y pesca fluvial de la Región de Murcia.)', NULL, 14079, NULL, 'ES0000507', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Charrán patinegro', 'Thalasseus sandvicensis', 'fauna', 'Ave marina', 'Costas, bahías y salinas; pesca sobre aguas someras', 'Anexo II. Lista de especies en peligro o amenazadas.', 'Charrán grande y pálido, con un penacho negro despeinado en la nuca y un pico negro rematado en amarillo, como si lo hubiera mojado en mostaza. Pesca zambulléndose de golpe desde varios metros de altura. Fuera de la época de cría pierde el negro de la frente y queda con la coronilla blanca.', NULL, 'Punta amarilla en el pico negro; Nuca con plumas negras erizadas, en penacho; Se lanza al agua en picado, plegando las alas', 'Otoño e invierno principalmente', 'https://inaturalist-open-data.s3.amazonaws.com/photos/606127388/original.jpg', 'Diego González Dopico (CC BY 4.0) · GBIF', NULL, NULL, 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"Directiva Aves 2009/147/CE (Red Natura 2000)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 81 ocurrencias de GBIF dentro de este espacio.', 'Chordata', 'Aves', NULL, NULL, 'Thalasseus', 'LC (Preocupación menor)', 'Directiva Aves 2009/147/CE (Red Natura 2000)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 12147, NULL, 'ES0000507', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Pardela balear', 'Puffinus mauretanicus', 'fauna', 'Ave marina', 'Mar abierto y aguas costeras; cría solo en las Baleares', 'En Peligro de Extinción', 'Pardela mediana, parda por arriba y sucia por debajo, que vuela en bandos bajos y rasantes alternando planeos y series de aleteos rápidos. Es el ave marina más amenazada de Europa: cría únicamente en las Baleares y su población total se cuenta por miles.', NULL, 'Vuelo bajo y rasante, alternando planeo y aleteos rápidos; Partes inferiores pardo sucio, sin blanco limpio; Suele verse en bandos que siguen la línea de costa', 'Sobre todo de final de invierno a verano', 'https://commons.wikimedia.org/wiki/Special:FilePath/Puffinus_mauretanicus.jpg?width=1280', 'Conselleria de Medi Ambient i Mobilitat, Govern des Illes Balears (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 5, '{"categoria":"CEEA: En peligro de extinción (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 5, '{"categoria":"CEEA: En peligro de extinción (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 1, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 9 ocurrencias de GBIF dentro de este espacio.', 'Chordata', 'Aves', 'Procellariiformes', 'Procellariidae', 'Puffinus', 'CR — En peligro crítico (Lista Roja mundial de la UICN, 2018)', 'CEEA: En peligro de extinción (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011) · Anexo IV (Ley 42/2007, de 13 de diciembre, del Patrimonio Natural y de la Biodiversidad. BOE 299, de 14 de diciembre de 2007)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 11691, NULL, 'ES0000507', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Págalo grande', 'Stercorarius skua', 'fauna', 'Ave marina', 'Mar abierto y aguas costeras en invierno', 'Protegida (LESRPE)', 'El mayor de los págalos, pardo y macizo, del tamaño de una gaviota grande, con manchas blancas muy llamativas en la base de las alas que destellan a cada aleteo. Es un pirata consumado: acosa a alcatraces y gaviotas y también captura presas directamente.', NULL, 'Manchas blancas conspicuas en la base de las primarias; Plumaje pardo uniforme y cuerpo macizo, de gaviota grande; Vuelo pesado que se vuelve ágil al perseguir a otras aves', 'Otoño e invierno', 'https://commons.wikimedia.org/wiki/Special:FilePath/Great_Skua.jpg?width=1280', 'Andreas Trepte (CC BY-SA 2.5) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental. La lista oficial la cita como Catharacta skua; EIDOS (IEPNB) acepta Stercorarius skua.', 'Chordata', 'Aves', 'Charadriiformes', 'Stercorariidae', 'Stercorarius', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 14044, NULL, 'ES0000507', 1, '{"tipos":["en concentración"],"etiqueta":"En paso migratorio","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Gaviota patiamarilla', 'Larus michahellis', 'fauna', 'Ave marina', 'Costas, puertos, playas, acantilados y basureros', 'Anexo III', 'La gaviota grande más común del Mediterráneo: manto gris claro, patas amarillas y un pico robusto con una mancha roja en la mandíbula inferior. Es oportunista hasta el extremo —pesca, roba, carroñea y frecuenta puertos y vertederos— y sus colonias ocupan islotes y cortados costeros.', NULL, 'Patas amarillas y pico amarillo con mancha roja; Manto gris claro con puntas de las alas negras y espejos blancos; Los jóvenes son pardos moteados y tardan cuatro años en cambiar', 'Todo el año', 'https://commons.wikimedia.org/wiki/Special:FilePath/Larus_michahellis_LC0046.jpg?width=1280', 'Jörg Hempel (CC BY-SA 2.0 de) · Wikimedia Commons', NULL, NULL, 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 1, '{"categoria":"Sin figura de protección","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Confirmada además por 331 ocurrencias de GBIF dentro de este espacio.', 'Chordata', 'Aves', 'Charadriiformes', 'Laridae', 'Larus', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2019)', 'Sin figura de protección de ámbito estatal (LESRPE/CEEA) en EIDOS (IEPNB)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 14061, NULL, 'ES0000507', 0, '{"tipos":["permanente"],"etiqueta":"Residente todo el año","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
    UNION ALL
    SELECT 'Pardela cenicienta atlántica', 'Calonectris borealis', 'fauna', 'Ave marina', 'Mar abierto; cría en islas atlánticas y se ve en paso por el Mediterráneo occidental', 'Protegida (LESRPE)', 'Gemela de la pardela cenicienta mediterránea, algo mayor y más robusta, con el mismo vuelo planeador en arcos sobre el mar. Cría en el Atlántico —Canarias, Azores, Madeira— y entra en el Mediterráneo occidental fuera de la época de cría.', NULL, 'Silueta grande y pesada planeando en arcos sobre las olas; Dorso pardo uniforme y vientre blanco limpio; Alas más anchas y batido más lento que en gaviotas', 'De verano a otoño', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cory''s_Shearwater_from_the_Crossley_ID_Guide_Britain_and_Ireland_crop.jpg?width=1280', 'Richard Crossley (CC BY-SA 3.0) · Wikimedia Commons', NULL, NULL, 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del catálogo universal"}', 2, '{"categoria":"LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)","ambito":"estatal","origen":"spainStatus del park.json"}', 0, 1, NULL, 'Especie de la lista oficial del sitio Natura 2000 ES0000507 (EEA/BISE, Site_Species_List). Sin ocurrencia de GBIF verificada dentro del espacio: la cita es documental.', 'Chordata', 'Aves', 'Procellariiformes', 'Procellariidae', 'Calonectris', 'LC — Preocupación menor (Lista Roja mundial de la UICN, 2018)', 'LESRPE: En régimen de protección especial (Real Decreto 139/2011, de 4 de febrero, para el desarrollo del Listado de Especies Silvestres en Régimen de Protección Especial y del Catálogo Español de Especies Amenazadas. BOE 46, de 23 de febrero de 2011)', 'No incluida en el Catálogo Regional de especies protegidas de la Región de Murcia', NULL, 32348, NULL, 'ES0000507', 1, '{"tipos":["reproductora"],"etiqueta":"Reproductora: cría aquí","sitios":[{"code":"ES0000507","name":"Espacio marino de los Islotes Litorales de Murcia y Almería","seccion":"3.2"}],"fuente":"Formulario Normalizado de Datos del sitio Red Natura 2000 ES0000507 (Espacio marino de los Islotes Litorales de Murcia y Almería), sección 3.2"}'
